mapper.update:
/* AuthMapper.revokeTokenById */
    UPDATE TB_AUTH_TOKEN
       SET REVOKED_YN = 'Y'
         , REVOKED_DTIME = NOW()
         , UPDATE_NO = #{userCd}
         , UPDATE_DATE = NOW()
     WHERE CMPNY_CD = #{cmpnyCd}
       AND USER_CD = #{userCd}
       AND TOKEN_ID = #{tokenId}
       AND REVOKED_YN = 'N'

mapper.insert:
/* AuthMapper.insertRotatedToken */
    INSERT INTO TB_AUTH_TOKEN (
        CMPNY_CD
        , USER_CD
        , TOKEN_ID
        , LOGIN_ID
        , CLIENT_TYPE
        , DEVICE_ID
        , REFRESH_TOKEN_HASH
        , ISSUED_DTIME
        , EXPIRE_DTIME
        , REVOKED_YN
        , REVOKED_DTIME
        , INSERT_NO
        , INSERT_DATE
    ) VALUES (
        #{cmpnyCd}
        , #{userCd}
        , #{tokenId}
        , #{loginId}
        , #{clientType}
        , #{deviceId}
        , #{refreshTokenHash}
        , NOW()
        , #{expireDtime}
        , 'N'
        , NULL
        , #{userCd}
        , NOW()
    )

mapper.select:
/* AuthMapper.countActiveByLoginId */
    SELECT COUNT(1)
    FROM TB_AUTH_TOKEN
    WHERE CMPNY_CD = #{cmpnyCd}
      AND USER_CD  = #{userCd}
      AND LOGIN_ID = #{loginId}
      AND REVOKED_YN = 'N'
      AND EXPIRE_DTIME > NOW()

/* AuthMapper.countActiveOtherLogin */
    SELECT COUNT(1)
    FROM TB_AUTH_TOKEN
    WHERE CMPNY_CD = #{cmpnyCd}
      AND USER_CD  = #{userCd}
      AND CLIENT_TYPE = #{clientType}
      AND LOGIN_ID != #{loginId}
      AND REVOKED_YN = 'N'
      AND EXPIRE_DTIME > NOW()

/* AuthMapper.selectGateUserInfo */
    SELECT
        CASE WHEN PWD_CHG_DTIME IS NULL THEN 'Y' ELSE 'N' END  AS pwdChgPendingYn
        , EMPLOYMENT_TYPE                                       AS employmentType
    FROM TB_USER
    WHERE CMPNY_CD = #{cmpnyCd}
      AND USER_CD  = #{userCd}
      AND USE_YN   = 'Y'
    LIMIT 1
